// Shape of /build-info.json — generated by scripts/generate-build-info.mjs on
// every publish and staged onto the site by scripts/sync-adsite.sh. Fetched
// at runtime so the "latest build" section updates without a vite rebuild.

export interface BuildInfoFinding {
  id: string
  severity: string
  pkg: string
  installed: string
  title: string
}

export interface BuildInfoScan {
  image?: string
  scanned?: boolean
  reason?: string
  counts?: Record<string, number>
  total?: number
  top?: BuildInfoFinding[]
  scannedAt?: string
}

export interface BuildInfo {
  schemaVersion: number
  buildNumber: number
  commit: string
  shortCommit: string
  publishedAt: string | null
  generatedAt: string
  images: Record<string, { image: string; tag: string; digest: string | null }>
  runner?: { artifact: string; sha256: string }
  trivy: {
    available: boolean
    scannedAt: string | null
    reason?: string
    images: Record<string, BuildInfoScan>
    source?: BuildInfoScan | null
  }
}
